<script setup>
import MarkdownContent from './MarkdownContent.vue'
import {computed,ref,watch} from 'vue'
import ChangeMethodIllustration from './ChangeMethodIllustration.vue'
import {methodVisuals} from '../method-visuals.js'
import WorkspaceIcon from './WorkspaceIcon.vue'
import WorkspaceDrawer from './WorkspaceDrawer.vue'
import ChangeMethodHelp from './ChangeMethodHelp.vue'
import RetrievalChangeGuide from './RetrievalChangeGuide.vue'
import LogConsultation from './LogConsultation.vue'
import {proposedChange,changeAnalysisContext,indexChangeTypes} from '../change-analysis-prompt.js'
import {recommendedNextStep} from '../retrieval-change-options.js'
import {supplementSource} from '../knowledge-supplement.js'
import {changeRunBlocker} from '../change-run-status.js'
import {runBriefing} from '../journey-guidance.js'
import PlanTrialResult from './PlanTrialResult.vue'
import {trialMatches,trialFinished,trialUsesHistoricalReference} from '../plan-trial.js'
const props=defineProps({view:Object,caseId:String,type:String,nextK:Number,answerPrompt:String,defaultAnswerPrompt:String,index:Object,knowledge:Object,options:Array,indices:{type:Array,default:()=>[]},indexId:String,retrievalMode:String,contextStrategy:String,candidatePool:Number,prediction:String,userRisk:String,indexJob:Object,indexLoading:Boolean,busy:Boolean,locked:Boolean,confirmed:Boolean,note:String,preview:Object,canPreview:Boolean,session:Object,flow:Object,trial:Object})
const emit=defineEmits(['update:caseId','update:type','update:nextK','update:answerPrompt','update:confirmed','update:note','update:indexId','update:retrievalMode','update:contextStrategy','update:candidatePool','update:prediction','update:userRisk','prepare-index','refresh-indices','cancel-index','read-index','submit','trial','compare','refresh-baseline','draft','return','connect','knowledge','supplement','preview','tests'])
const contextOpen=ref(false),intentions=ref([]),settings=ref(null),guideOpen=ref(false)
const selected=computed(()=>props.view?.run.case_results.find(c=>c.case_id===props.caseId))
const answer=computed(()=>(props.view?.effective_answer_results||[]).find(a=>a.case_id===props.caseId))
const analysisOptions=computed(()=>({...props}))
const plan=computed(()=>proposedChange(analysisOptions.value))
const next=computed(()=>recommendedNextStep(props.view,props.caseId))
const needsIndex=computed(()=>indexChangeTypes.includes(props.type))
const autoPrepare=computed(()=>['CHUNKING_CHANGE','EMBEDDING_CHANGE'].includes(props.type)&&!props.index)
const chunkBound=computed(()=>props.view?.run.controls?.eval_set_snapshot?.cases?.some(c=>c.relevant_chunk_ids?.length))
const baselineCalls=computed(()=>props.view.run.execution_order.length*(Number(!!props.view.run.retrieval_config.query_rewrite)+Number(!!props.view.run.retrieval_config.rerank)+(props.view.run.verify_answers?2:0)))
const blocker=computed(()=>changeRunBlocker({...props,plan:plan.value,chunkBound:chunkBound.value}))
const canRun=computed(()=>!blocker.value)
function fixBlocker(){const action=blocker.value?.action;if(action==='settings'){const target=settings.value?.querySelector('input,select,textarea')||settings.value?.querySelector('.knowledge-assist button')||settings.value;target?.scrollIntoView({block:'center',behavior:'smooth'});target?.focus({preventScroll:true})}else if(action)emit(action)}
const title=computed(()=>props.type==='CONTEXT_STRATEGY_CHANGE'?visual.value.title:({CANDIDATE_POOL_CHANGE:'扩大候选范围',TOP_K_CHANGE:'调整回答参考的资料条数',CHUNKING_CHANGE:'让条件与例外尽量留在一起'})[props.type]||props.options.find(o=>o.value===props.type)?.label||'选择一个改法')
const explorationReasons={KNOWLEDGE_UPDATE:'用本题参考答案补充知识库，再用原题检查效果。',CANDIDATE_POOL_CHANGE:'先扩大查找范围，再看能否选到更合适的资料。效果需要复测。',TOP_K_CHANGE:'调整交给模型的资料条数，看看回答是否更完整。',CHUNKING_CHANGE:'换一种文档切法，检查条件与例外能否一起被找到。'}
const reason=computed(()=>next.value.method===props.type?next.value.reason:explorationReasons[props.type]||'先试这一种改法，再用原题比较效果。当前还不能确定问题原因。')
const brief=computed(()=>runBriefing({session:props.session,index:props.index||props.view?.run.controls.index_snapshot,cases:(props.view?.run.controls.eval_set_snapshot.cases||[]).filter(c=>c.partition!=='HOLDOUT'),config:plan.value.afterConfig,verifyAnswers:props.view?.run.verify_answers}))
const matchingTrial=computed(()=>trialMatches(props.trial,{...props,afterConfig:plan.value.afterConfig}))
const tried=computed(()=>matchingTrial.value&&trialFinished(props.trial))
const historicalReference=computed(()=>trialUsesHistoricalReference(matchingTrial.value?props.trial:null,props.view))
const fullReady=computed(()=>tried.value&&!historicalReference.value)
const trialCalls=computed(()=>Number(!!plan.value.afterConfig?.query_rewrite)+Number(!!plan.value.afterConfig?.rerank)+(props.view?.run.verify_answers?2:0))
const presets=[{id:'conditions',label:'先核对适用条件',rule:'回答前先核对政策的适用条件、时间限制和例外；不要把一般规则直接套用到例外情况。'},{id:'clarify',label:'缺信息先追问',rule:'缺少适用政策所需的用户信息时，先提出具体澄清问题，不自行补全前提或承诺结果。'},{id:'sources',label:'回答注明依据',rule:'在回答中注明实际使用的资料编号；给定资料未包含答案时，明确说明资料不足，不编造政策。'}]
watch(()=>[props.caseId,props.type],()=>{intentions.value=[];guideOpen.value=false})
function applyIntentions(){const base=props.view?.run.retrieval_config.answer_prompt||props.defaultAnswerPrompt||'';emit('update:answerPrompt',base+(intentions.value.length?'\n\n本次追加回答规则：\n'+presets.filter(p=>intentions.value.includes(p.id)).map(p=>'- '+p.rule).join('\n'):''))}
const visual=computed(()=>{
 const base=methodVisuals[props.type]||methodVisuals.QUERY_REWRITE_TOGGLE
 if(props.type==='CONTEXT_STRATEGY_CHANGE'&&props.contextStrategy==='SELECTED')return {...base,title:'先只读查到的内容',caption:'这次去掉额外前后文，试试能否减少无关内容的干扰。',steps:['不带前文','查到的内容','不带后文']}
 if(props.type==='CONTEXT_STRATEGY_CHANGE'&&props.contextStrategy==='PARENT')return {...base,title:'连同这一节一起读',caption:'把查到内容所在的这一节一起给 AI，避免漏掉同一节里的说明。',steps:['这一节前文','查到的内容','这一节后文']}
 if(props.type==='RETRIEVAL_MODE_CHANGE'&&props.retrievalMode==='BM25')return {...base,title:'沿着关键词找资料',caption:'按问题中的词语匹配资料。',steps:['关键词','匹配词语','取资料']}
 if(props.type==='RETRIEVAL_MODE_CHANGE'&&props.retrievalMode==='VECTOR')return {...base,title:'按含义找相近资料',caption:'用问题的含义匹配相近资料。',steps:['问题含义','相近资料','取资料']}
 return base
})
const numeric=computed(()=>['CANDIDATE_POOL_CHANGE','TOP_K_CHANGE'].includes(props.type))
const reference=computed(()=>{try{return supplementSource(props.view,props.caseId).reference}catch{return ''}})
function run(mode){if(!canRun.value||mode==='FULL'&&!fullReady.value)return;emit('update:confirmed',true);emit(mode==='FULL'?'submit':'trial')}
</script>
<template>
 <div class="change-plan-editor">
  <ol class="plan-steps" aria-label="实验进度"><li class="completed"><span><WorkspaceIcon name="check" :size="16" /></span>初测完成</li><li aria-current="step"><span>2</span>选择改法</li><li><span>3</span>复测比较</li></ol>
  <div class="change-plan-heading"><div><span class="eyebrow">本次尝试 · {{tried?'本题已试跑':'先试本题'}}</span><div class="change-plan-title"><h2>{{title}}</h2><ChangeMethodHelp :type="type" :label="title" /></div></div><button type="button" class="text-button" :disabled="busy" @click="emit('return')">返回本题结果</button></div>
  <div class="change-plan-columns">
   <section class="change-plan-controls" aria-label="确认本次实验方案">
    <section class="case-reminder" aria-label="本次要改进的题目"><div class="case-reminder-header"><div class="case-reminder-label"><WorkspaceIcon name="chat" :size="21" /><span>本次要改进的题目</span></div><button type="button" class="text-button" @click="contextOpen=true">看原回答 →</button></div><h3>{{selected?.query}}</h3></section>
    <section v-if="!numeric" class="method-hero" :class="{'method-hero-direct':type==='CONTEXT_STRATEGY_CHANGE'}" aria-label="本次修改图解"><div class="method-hero-copy"><span class="visual-caption">修改示意</span><h3>{{visual.title}}</h3><p>{{visual.caption}}</p><span v-if="index&&needsIndex" class="preparation-chip"><WorkspaceIcon name="check" :size="14" />资料已就绪</span><span v-else-if="type==='ANSWER_PROMPT_CHANGE'&&plan.valid" class="preparation-chip"><WorkspaceIcon name="check" :size="14" />规则已修改</span></div><figure><ChangeMethodIllustration :type="type" :retrieval-mode="retrievalMode" :context-strategy="contextStrategy" :ready="type==='KNOWLEDGE_UPDATE'?!!index:plan.valid" /><figcaption><span v-for="label in visual.steps" :key="label">{{label}}</span></figcaption></figure></section>
    <fieldset ref="settings" :disabled="busy||locked">
     <RetrievalChangeGuide v-if="numeric" :view="view" :case-id="caseId" :type="type" :next-k="nextK" :candidate-pool="candidatePool" :index="index" @candidates="contextOpen=true" />
     <label v-if="type==='RETRIEVAL_MODE_CHANGE'">本次查找方式<select :value="retrievalMode" @change="emit('update:retrievalMode',$event.target.value)"><option value="VECTOR">按语义查找</option><option value="BM25">按关键词查找</option><option value="HYBRID">同时按关键词和语义查找</option></select></label>
     <div v-if="type==='ANSWER_PROMPT_CHANGE'" class="prompt-intentions"><div class="intent-heading"><strong>选一条要加的规则</strong><span v-if="intentions.length">已选 {{intentions.length}} 条</span></div><div class="intent-grid"><label v-for="p in presets" :key="p.id" :class="['intent-card',{selected:intentions.includes(p.id)}]"><span class="intent-symbol"><WorkspaceIcon :name="({conditions:'list',clarify:'help',sources:'document'})[p.id]" :size="24" /></span><input type="checkbox" v-model="intentions" :value="p.id" @change="applyIntentions" /><strong>{{p.label}}</strong></label></div><details><summary>查看完整规则 / 编辑</summary><h4>初测的完整规则</h4><pre>{{view.run.retrieval_config.answer_prompt||defaultAnswerPrompt||'旧记录未提供'}}</pre><label>本次完整回答规则<textarea :value="answerPrompt" rows="7" maxlength="16000" @input="emit('update:answerPrompt',$event.target.value)" /></label><p>评分规则沿用初测。</p></details></div>
     <p v-if="autoPrepare" class="preparation-note"><WorkspaceIcon name="clock" :size="16" />系统会先准备资料，再试跑当前题。</p>
     <section v-if="type==='KNOWLEDGE_UPDATE'" class="knowledge-assist" aria-label="AI 辅助补充资料"><details v-if="reference"><summary>查看本题补充依据</summary><blockquote>{{reference}}</blockquote><p class="muted">原题用于检查这次补充，最终效果还需用其他题验证。</p></details><p v-else>这题还没有参考答案，请先在测试题中补充。</p><div class="button-row"><button v-if="!index" type="button" class="primary" :disabled="!reference||busy||session?.credential_status!=='PRESENT'||session?.text_connection_status!=='READY'" @click="emit('supplement')"><WorkspaceIcon name="chat" :size="18" />{{busy?'AI 正在整理…':'AI 整理并补充到知识库'}}</button><button type="button" :class="index?'secondary':'text-button'" @click="emit('knowledge')">{{index?'查看已补充的资料 →':'自行添加资料 →'}}</button></div></section>
     <div v-if="['CANDIDATE_POOL_CHANGE','TOP_K_CHANGE'].includes(type)" class="plan-quick-control">
      <label v-if="type==='CANDIDATE_POOL_CHANGE'">候选范围<input :value="candidatePool" aria-label="候选范围" type="number" min="20" max="100" @input="emit('update:candidatePool',$event.target.value===''?undefined:Number($event.target.value))" /><span>条</span></label>
      <label v-else>最终参考<input :value="nextK" aria-label="最终参考条数" type="number" min="1" max="20" @input="emit('update:nextK',$event.target.value===''?undefined:Number($event.target.value))" /><span>条</span></label>
      <span class="unchanged-setting">{{type==='CANDIDATE_POOL_CHANGE'?'最终最多 '+view.run.retrieval_config.top_k+' 条不变':'候选上限 '+(view.run.retrieval_config.candidate_pool_size??20)+' 条不变'}}</span>
     </div>
    </fieldset>
     <p v-if="brief.budget!=null&&brief.totalCalls>brief.budget" class="note warning">预计调用超过上限，可能只完成部分题。请先核对模型预算。</p>
     <div v-if="type!=='KNOWLEDGE_UPDATE'||index" class="run-scope"><span class="run-scope-icon"><WorkspaceIcon name="refresh" :size="24" /></span><div><strong>先快速试本题，再决定是否复测全部</strong><p>本题预计 {{trialCalls}} 次调用；全部 {{brief.count}} 题预计 {{brief.totalCalls}} 次调用，最多同时跑 3 题。</p></div></div>
     <p v-if="historicalReference&&!blocker" class="historical-reference" role="status">可以先试本题。旧评分仅作参考，整批比较前再更新初测。</p>
     <section v-if="blocker" id="change-run-blocker" :class="['run-blocker','blocker-'+blocker.tone]" role="status" aria-live="polite"><WorkspaceIcon :name="blocker.tone==='warning'?'alert':'log'" :size="26" /><div><h3>{{blocker.title}}</h3><p>{{blocker.detail}}</p><button v-if="blocker.action" type="button" class="secondary" @click="fixBlocker">{{blocker.label}} <WorkspaceIcon name="arrow" :size="16" /></button></div></section>
     <div v-if="type!=='KNOWLEDGE_UPDATE'||index" class="plan-run-actions"><button type="button" :class="fullReady?'secondary':'primary'" :disabled="!canRun" :aria-describedby="blocker?'change-run-blocker':undefined" @click="run('TRIAL')">{{tried?'重新试本题':'先快速试本题'}} <WorkspaceIcon name="arrow" :size="18" /></button><button type="button" :class="fullReady?'primary':'secondary'" :disabled="!canRun||!fullReady" @click="run('FULL')">复测全部 {{brief.count}} 题</button><button type="button" class="text-button" :disabled="!plan.valid||busy||locked" @click="emit('update:confirmed',true);emit('draft')">仅保存方案</button></div>
     <p v-if="trial&&!matchingTrial" class="trial-changed">方案已改动，先重新试本题。</p>
     <PlanTrialResult v-if="matchingTrial" :trial="trial" :baseline="view" :case-id="caseId" @compare="emit('compare')" />
     <section v-if="tried&&historicalReference&&!blocker" class="run-blocker" role="status"><WorkspaceIcon name="refresh" :size="26" /><div><h3>准备整批比较？先更新初测</h3><p>原评分来自旧程序，不能直接算改善。预计 {{baselineCalls}} 次调用，旧记录保留。</p><button type="button" class="secondary" @click="emit('refresh-baseline')">更新初测（{{brief.count}} 题） <WorkspaceIcon name="arrow" :size="16" /></button></div></section>
     <details class="plan-more"><summary>原理、依据与用量说明</summary><p>{{reason}}</p><p>{{plan.aim}}</p><p>{{plan.risk}}</p><p>沿用原题与评分标准，比较目标题和其他题的变化；重试也会计入调用上限。</p><p>系统会保存方案、准备资料、应用、复测和比较。已发出的调用可能产生用量。</p><details v-if="!numeric&&type!=='KNOWLEDGE_UPDATE'" @toggle="guideOpen=$event.target.open"><summary>{{type==='CHUNKING_CHANGE'?'看实际切块预览':'看本题查找记录'}}</summary><RetrievalChangeGuide v-if="guideOpen" :view="view" :case-id="caseId" :type="type" :index="index" :retrieval-mode="retrievalMode" :context-strategy="contextStrategy" :answer-prompt="answerPrompt" @candidates="contextOpen=true" /></details></details>
   </section>
   <aside class="change-context" aria-label="本题记录与咨询"><div class="log-visual"><ChangeMethodIllustration type="LOGS" /><strong>带走完整记录</strong></div>
    <LogConsultation cards kind="plan" :view="view" :case-id="caseId" :context="changeAnalysisContext(analysisOptions)" :flow="flow" />
   </aside>
  </div>
  <WorkspaceDrawer :open="contextOpen" title="本题原文与记录" @close="contextOpen=false"><h3>{{selected?.query}}</h3><h4>原回答</h4><MarkdownContent class="agent-response" :source="answer?.turn_evidence?.[0]?.response||'未保存回答'" /><h4>初测实际提供的资料</h4><article v-for="r in selected?.results" :key="r.chunk_id"><h4>{{r.document_id}} · {{r.chunk_id}}</h4><p>{{r.text}}</p></article><details><summary>候选及其原排名</summary><article v-for="(r,i) in selected?.pre_rerank_results" :key="r.chunk_id"><h4>{{i+1}} · {{r.document_id}}</h4><p>{{r.text}}</p></article></details></WorkspaceDrawer>
 </div>
</template>
<style scoped>
.change-plan-editor{--plan-line:#e0e3da}.plan-steps{display:flex;list-style:none;align-items:center;gap:24px;margin:0 0 24px;padding:0;color:var(--muted);font-size:14px}.plan-steps li{display:flex;align-items:center;gap:10px}.plan-steps li+li:before{content:"";width:40px;height:1px;background:var(--plan-line);margin-right:12px}.plan-steps li>span{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#e9ebe5}.plan-steps .completed>span{background:#e0e9d9;color:#485d45}.plan-steps [aria-current]{color:var(--text);font-weight:600}.plan-steps [aria-current]>span{color:#fff;background:#485d45}
.change-plan-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:20px}.change-plan-title{display:flex;align-items:center;gap:8px}.change-plan-heading h2{font-size:30px;line-height:1.4;margin:8px 0 0}.change-plan-columns{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:28px;align-items:start}.change-plan-controls{min-width:0;background:var(--color-surface);border:1px solid var(--plan-line);border-radius:12px;padding:24px}.change-plan-controls fieldset{border:0;padding:0;min-width:0}.change-plan-controls label{font-size:15px;margin:18px 0}.change-plan-controls input:not([type=checkbox]),.change-plan-controls select,.change-plan-controls textarea{font-size:15px}.change-plan-controls p{line-height:1.8}.change-plan-controls input[type=number]{max-width:120px}
.case-reminder{margin:0 0 20px;padding:17px 19px;border:1px solid #a8bfdf;border-left:4px solid #4779bd;border-radius:10px;background:#edf4ff;color:#244e83}.case-reminder-header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.case-reminder-label{display:flex;align-items:center;gap:9px;font-size:18px;font-weight:700}.case-reminder h3{font-size:20px;line-height:1.65;margin:12px 0 0;color:#233e62}.case-reminder button{font-size:14px;color:#315f9a;padding:0;min-height:28px}
.method-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(200px,260px);gap:16px;align-items:center;padding:12px 4px 22px;margin-bottom:20px;border-bottom:1px solid var(--plan-line)}.visual-caption{font-size:12px;color:#878976}.method-hero h3{font-size:21px;font-weight:600;line-height:1.6;margin:7px 0}.method-hero p{font-size:14px;color:var(--muted);margin:6px 0}.method-hero figure{margin:0;min-width:0}.method-hero figcaption{display:flex;justify-content:space-around;gap:6px;font-size:12px;color:#6e7565;margin-top:0;line-height:1.7}.preparation-chip{display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 8px;background:#edf2e6;color:#577047;border-radius:20px;margin-top:7px}
.method-hero.method-hero-direct{border-bottom:0;margin-bottom:0}.historical-reference{font-size:14px;color:#315f9a;background:#edf4ff;border-radius:8px;padding:10px 14px;margin:14px 0 0}
.intent-heading{display:flex;justify-content:space-between;gap:10px;align-items:center;font-size:15px}.intent-heading>span{font-size:13px;color:#58744b}.intent-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:14px 0 18px}.change-plan-controls .intent-card{display:grid;grid-template-columns:1fr 20px;align-items:start;gap:12px 6px;margin:0;padding:15px 13px;background:#faf9f4;border:1px solid var(--plan-line);border-radius:9px;cursor:pointer}.intent-card strong{grid-column:1/-1;font-size:14px;font-weight:500;line-height:1.5}.intent-symbol{display:grid;place-items:center;width:36px;height:36px;color:#7c8c69;border-radius:9px;background:#edf0e6}.intent-card input{width:18px;height:18px;margin:2px 0;accent-color:#557fad}.change-plan-controls .intent-card.selected{border-color:#8da9cc;background:#edf4ff}.intent-card.selected .intent-symbol{color:#5d7eaa;background:#e1ebfa}.intent-card:focus-within{outline:2px solid var(--color-focus);outline-offset:2px}.prompt-intentions pre{font-size:14px;white-space:pre-wrap;max-height:240px;overflow:auto}.prompt-intentions details{margin:16px 0}
.knowledge-assist{margin:0 0 18px}.knowledge-assist blockquote{margin:12px 0;padding:12px 16px;border-left:3px solid #8b9b7e;background:var(--color-canvas);white-space:pre-wrap;font-size:14px;line-height:1.8}.knowledge-assist .muted{font-size:13px;color:var(--muted)}.knowledge-assist .button-row{margin:14px 0}.preparation-note{display:flex;align-items:center;gap:8px;font-size:14px;background:#f0f3eb;padding:12px 14px;border-radius:8px}
.plan-quick-control{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:6px 0 18px}.plan-quick-control label{display:flex;align-items:center;gap:10px;margin:0}.plan-quick-control input{width:90px;margin:0}.unchanged-setting{font-size:14px;color:var(--muted);padding:9px 12px;background:var(--color-surface-subtle);border-radius:6px}
.run-scope{display:flex;align-items:center;gap:13px;padding:18px 0 0;border-top:1px solid var(--plan-line)}.run-scope-icon{display:grid;place-items:center;width:42px;height:42px;color:#788967;background:#eff2e9;border-radius:50%;flex-shrink:0}.run-scope strong{font-size:16px}.run-scope p{font-size:13px;color:var(--muted);margin:5px 0 0}.plan-run-actions{display:flex;align-items:center;gap:20px;margin:18px 0 0}.plan-run-actions>.primary{padding:13px 20px;font-size:16px}.plan-more{margin-top:20px!important}.plan-more p{font-size:14px;color:var(--muted)}
