.change-context{min-width:0;border:1px solid var(--plan-line);border-radius:12px;background:#faf9f4;overflow:hidden}.log-visual{display:grid;justify-items:center;padding:16px 20px 12px}.log-visual>svg{max-width:220px}.log-visual strong{font-size:15px;font-weight:500;color:#666e5d}.change-context :deep(.consultation-cards){border:0;border-radius:0;background:transparent;padding:14px 18px 20px;gap:12px}.change-context :deep(.consultation-cards>button){font-size:13px}
